type CTAField struct{ URLField, LabelField, Source string }

// DeriveCTAURLFields returns fields ending "_url" that have a sibling
// "<stem>_label" or "<stem>_text". The sibling test is load-bearing:
// site_assets.image/logo fields also end in "_url" (32 in the live library)
// and must never be touched by link resolution.
func DeriveCTAURLFields(inputSchema map[string]interface{}) []CTAField {
	fields, _ := inputSchema["fields"].(map[string]interface{})
	stems := map[string]string{} // stem -> label field
	for n := range fields {
		for _, suf := range []string{"_label", "_text"} {
			if strings.HasSuffix(n, suf) { stems[strings.TrimSuffix(n, suf)] = n }
		}
	}
	var out []CTAField
	for n, raw := range fields {
		if !strings.HasSuffix(n, "_url") { continue }
		label, ok := stems[strings.TrimSuffix(n, "_url")]
		if !ok { continue }
		spec, _ := raw.(map[string]interface{})
		src, _ := spec["source"].(string)
		out = append(out, CTAField{n, label, src})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].URLField < out[j].URLField })
	return out
}

